//! Candle's elementwise CUDA kernels, as PTX generated by cuda-oxide.
//!
//! The PTX is generated offline and committed, so this crate depends on
//! neither cuda-oxide nor pliron and needs no build script. Regenerate with
//! `cargo xtask gen-ptx` from the workspace this crate is developed in.
//!
//! Load a module through `CudaDevice::get_or_load_custom_func`, keyed by the
//! module name below. Do not route it through `candle_kernels::Module`, whose
//! index is positional into a fixed array and would collide.

/// PTX holding every binary entry point.
pub const BINARY: &str = include_str!("../ptx/binary.ptx");

/// PTX holding every unary entry point.
pub const UNARY: &str = include_str!("../ptx/unary.ptx");

/// PTX holding every fused family entry point.
///
/// What the entries share is that each takes its index from the launch
/// geometry rather than computing it, and each assumes contiguous f32
/// operands. Three also collapse a run of two elementwise kernels into one
/// pass; the other two are a single traversal Candle already performs, run
/// without an index computation. A caller that cannot establish the
/// preconditions evaluates the reference expression instead.
pub const FUSED: &str = include_str!("../ptx/fused.ptx");

/// Key for `get_or_load_custom_func` when loading [`BINARY`].
pub const BINARY_MODULE: &str = "oxide::binary";

/// Key for `get_or_load_custom_func` when loading [`UNARY`].
pub const UNARY_MODULE: &str = "oxide::unary";

/// Key for `get_or_load_custom_func` when loading [`FUSED`].
pub const FUSED_MODULE: &str = "oxide::fused";

