/// Every entry point in [`FUSED`].
///
/// Each takes its arguments positionally, every `size_t` as a `.u64` word,
/// and `fused_scale_mask_f32`'s `scale` as the single `.f32`, placed last so
/// the word-sized parameters stay contiguous:
///
/// ```text
/// fused_scale_mask_f32(ss: size_t, x: *const f32, mask: *const f32,
///                      out: *mut f32, scale: f32)
///     grid (ceil(ss / block), H, B), block (256, 1, 1)
///     b   = ctaid.z
///     row = (b * nctaid.y + ctaid.y) * ss
///     col = ctaid.x * ntid.x + tid.x, strided by ntid.x * nctaid.x
///                                     while col < ss
///     out[row + col] = (x[row + col] * scale + 0.0f) + mask[b * ss + col]
///
/// fused_bias_gelu_erf_f32(d: size_t, x: *const f32, bias: *const f32,
///                         out: *mut f32)
///     grid (ceil(d / block), rows, 1), block (256, 1, 1)
///     row = ctaid.y * d
///     col = ctaid.x * ntid.x + tid.x, strided while col < d
///     t   = x[row + col] + bias[col]
///     out[row + col] = t * normcdf(t)
///
/// fused_bias_residual_f32(d: size_t, x: *const f32, bias: *const f32,
///                         residual: *const f32, out: *mut f32)
///     same geometry
///     out[row + col] = (x[row + col] + bias[col]) + residual[row + col]
///
/// fused_bias_f32(d: size_t, x: *const f32, bias: *const f32, out: *mut f32)
///     same geometry
///     out[row + col] = x[row + col] + bias[col]
///
/// fused_permute12_f32(d: size_t, src: *const f32, out: *mut f32)
///     grid (D2, D1, B), block (min(round_up_32(d), 256), 1, 1)
///     b = ctaid.z,  i = ctaid.y,  j = ctaid.x
///     D1 = nctaid.y,  D2 = nctaid.x
///     k = tid.x, strided by ntid.x while k < d
///     out[((b * D2 + j) * D1 + i) * d + k]
///         = src[((b * D1 + i) * D2 + j) * d + k]
///
/// fused_scale_mask_softmax_f32(scores: *const f32, mask: *const f32,
///                              out: *mut f32, scale: f32)
///     grid (S, H, B), block (32, 1, 1)
///     s = ctaid.x,  h = ctaid.y,  b = ctaid.z
///     S = nctaid.x, H = nctaid.y
///     row  = ((b * H + h) * S + s) * S
///     mrow = (b * S + s) * S
///     col  = tid.x, strided by 32 while col < S
///     t(col) = (scores[row + col] * scale + 0.0f) + mask[mrow + col]
///     out[row + ...] = softmax over t, Candle's own reduction
/// ```
///
/// `fused_scale_mask_f32` reads `x` as `[B, H, S, S]` and `mask` as
/// `[B, 1, S, S]`, with `ss = S*S`. The head count arrives as `nctaid.y`
/// rather than as a parameter. `rows` for the bias entries is every
/// dimension but the last. `fused_permute12_f32` copies a rank-4 tensor
/// whose logical shape is `[B, D2, D1, d]` over a contiguous source of shape
/// `[B, D1, D2, d]`, and takes both `D1` and `D2` from the grid. Every
/// operand of every entry must be contiguous and f32.
///
/// No entry takes an element count, and none divides: the launch is shaped
/// like the tensor, so every index term is a special register or the
/// induction variable. CUDA caps `gridDim.y` and `gridDim.z` at 65535, so a
/// caller whose `H`, `B`, `D1` or `rows` exceeds that evaluates the
/// reference expression instead. `ss` and `d` must be non-zero, as loop
/// bounds rather than as divisors.
///
/// `fused_permute12_f32` takes its column from `tid.x` alone, stepping by
/// `ntid.x`, because `ctaid.x` names a permuted dimension and cannot also
/// index the column. `fused_scale_mask_softmax_f32` takes its column from
/// `tid.x` too, stepping by a literal 32, since its block is fixed at one
/// warp. Every other entry takes its column from
/// `ctaid.x * ntid.x + tid.x`, stepping by `ntid.x * nctaid.x`.
///
/// `fused_scale_mask_softmax_f32` folds Candle's softmax onto the scale and
/// the mask, so the score tensor is never written between the two. Its block
/// must be exactly one warp: the reduction is `softmax_f32`'s own butterfly
/// over the lanes 16, 8, 4, 2 and 1, reproduced term for term, and it needs
/// no shared memory and no barrier. `scores` is `[B, H, S, S]`, `mask` is
/// `[B, 1, S, S]`, the last two dimensions of `scores` must be equal because
/// the column count and the grid's x extent are the same number, and `out`
/// is written twice, so it may not alias either input.
///
/// `fused_scale_mask_f32` replaces `affine_f32` followed by `badd_f32`,
/// and `affine_f32`'s body is
/// `x * mul + add`, which Candle reaches with `add` zero through
/// `Tensor::affine(scale, 0.0)`. That add changes one value: a product of
/// `-0.0` becomes `+0.0`, since `-0.0 + 0.0` is `+0.0` under
/// round-to-nearest. Dropping it disagrees with the reference whenever the
/// mask element is `-0.0` as well. The three roundings are each kept
/// separate: the family compiles with FMA contraction off, so the multiply
/// and the zero add are never contracted.
pub const FUSED_ENTRIES: &[&str] = &[
    "fused_scale_mask_f32",
    "fused_bias_gelu_erf_f32",
    "fused_bias_residual_f32",
    "fused_bias_f32",
    "fused_permute12_f32",
    "fused_scale_mask_softmax_f32",
];

/// Whether `module` provides `name`. Returns false for an unknown module.
pub fn has_entry(module: &str, name: &str) -> bool {
    match module {
        BINARY_MODULE => BINARY_ENTRIES.contains(&name),
        UNARY_MODULE => UNARY_ENTRIES.contains(&name),
        FUSED_MODULE => FUSED_ENTRIES.contains(&name),
        _ => false,
    }
}

/// The PTX for `module`, or `None` if the name is not one of this crate's.
pub fn ptx_for(module: &str) -> Option<&'static str> {
    match module {
        BINARY_MODULE => Some(BINARY),
        UNARY_MODULE => Some(UNARY),
        FUSED_MODULE => Some(FUSED),
        _ => None,
    }
}
